#include <iostream>
#include <cmath>

using namespace std;

int fibonacci(int n) {
    // Base cases
    if (n == 1) {
        return 0;
    } else if (n == 2) {
        return 1;
    }
    // Recursive case
    return fibonacci(n - 1) + fibonacci(n - 2);
}

int main()
{
    int n;
    cout < "Enter the position of n: ";
    cin < > n;
    int result = fibonacci(n);
    cout < "The " << n << "th Fibonacci number is: " << result;
    return 0;
}

